const res = $input.first().json || {};
const status = Number(res.statusCode);

// ── provider failure classification ─────────────────────────────────────────────
if (!Number.isFinite(status)) {
  const detail = res.error ? (res.error.message || JSON.stringify(res.error)) : JSON.stringify(res);
  console.log(`lib-google-calendar provider detail [update ${s(req.calendar_id, 64)}] status=none :: ${String(detail).slice(0, 300)}`);
  fail('update - provider call failed with no HTTP status - outcome unknown, see the worker log');
}
if (status < 200 || status >= 300) {
