  const detail = e.message || (typeof body === 'string' ? body : JSON.stringify(body).slice(0, 300));
  console.log(`lib-google-calendar provider detail [update ${s(req.calendar_id, 64)}] status=${status} :: ${String(detail).slice(0, 300)}`);
  if (status === 401 || status === 403) fail(`update - provider auth failed (${status}) - re-connect the 'Google Calendar account' credential in n8n, its stored OAuth tokens look stale`);
  if (status === 404) fail(`update - calendar or event not found for ${s(req.calendar_id, 64)}`);
  if (status === 429) fail('update - provider rate limit hit - retry later');
  fail(`update - provider call failed (${status}) - see the worker log for the provider detail`);
