  end:   (ev.end   && (ev.end.dateTime   || ev.end.date))   || null,
} } }];

// Return: delete — the HTTP node runs fullResponse + neverError, so a non-2xx from
// Google arrives HERE as data ({statusCode, body}) and is classified in code with a
// REAL status rather than swallowed. onError:continueRegularOutput additionally
// catches the transport-level failures (timeout, DNS), which arrive as {error: …}
