const res = $input.first().json || {};
const status = Number(res.statusCode);

// ── provider failure classification ─────────────────────────────────────────────
if (!Number.isFinite(status)) {
  const detail = res.error ? (res.error.message || JSON.stringify(res.error)) : JSON.stringify(res);
  console.log(`lib-google-calendar provider detail [delete ${s(req.calendar_id, 64)}] status=none :: ${String(detail).slice(0, 300)}`);
  fail('delete - provider call failed with no HTTP status - outcome unknown, see the worker log');
}
// 410 Gone = already deleted. The desired state holds, so this is success by other
// means - failing an approved proposal because the outcome was already achieved
// teaches the operator to distrust real failures. MUST come before the generic
// non-2xx branch below.
if (status === 410) {
  return [{ json: { ok: true, deleted: req.event_id } }];
}
if (status < 200 || status >= 300) {
  const body = res.body || {};
  const e = body.error || {};
  const detail = e.message || (typeof body === 'string' ? body : JSON.stringify(body).slice(0, 300));
